        tur: tur
    };

} else {
    //搜索跳详情重定向处理
    let ii = String(book.bookUrl).startsWith('http');
    if (ii) {
        bkid = String(book.bookUrl).match(/\d{5,}(?=\/?$)/);
        java.put('bkid', bkid);
        book.bookUrl = `data:page;base64,${java.base64Encode('https://m.qidian.com/book/'+bkid)},{"type":"lyc"}`;
    }

    let sinfo = source.getLoginInfoMap();
    bkid = java.get('bkid');
    let rr = cache.getFromMemory('zs' + bkid);
    let rr2 = cache.get('zss' + bkid);
    let rr3 = cache.get('zst' + bkid);
    let url1 = QDSign("v3/bookdetail/get", ["bookId=" + bkid, "isOutBook=0"]);
    let url2 = gethd(qdturl + '/info/' + bkid);
    let url3 = gethd(`https://pre-api.tuishujun.com/api/searchBook?search_value=${book.name}&page=1&pageSize=3`);

    if (!String(rr).startsWith("{")) {
        rr = java.ajax(url1);
        cache.put('zs' + bkid, rr, 86400);
    }
    if (!String(rr2).trim().startsWith("<")) {
        rr2 = java.ajax(url2,9000);
        rr3 ? cache.put('zss' + bkid, rr2, 86400) :
            cache.put('zss' + bkid, rr2, 86400 * 2);
    }
    if (!String(rr3).startsWith("{")) {
        rr3 = java.ajax(url3,9000);
        rr3.includes(`"data":[]`) ?
            cache.put('zst' + bkid, rr3, 864000) :
            cache.put('zst' + bkid, rr3, 864000 * 2);
    }

    //获取起点图作者
    let au = gets('class.media-body@tr.1@a.-1@text', rr2);
    //获取推书君
    let aly = new JavaImporter(Packages.com.jayway.jsonpath);
    with(aly) {
        var jsonp = JsonPath.using(
            Configuration.builder()
            .options(Option.SUPPRESS_EXCEPTIONS)
            .build()
        ).parse(rr3);
    }
    let tsin = jsonp.read(`$..data[?(@.author_nickname=="${(book.author+'').replace('\u200b','')||au}")]['score','score_people_number','first_subscribe']`);
    let tspf = '',
        tssd = '';
    if (tsin != '[]') {
        //评分
        tsin[0].score_people_number != 0 && (tspf = `${tsin[0].score}分 (${tsin[0].score_people_number}人)`);
        //首订
        (tsin[0].first_subscribe + []).length > 4 && (tssd = `首订：${tsin[0].first_subscribe}`);
    }

    //获取起点图信息
    //获取收藏数保留一位小数，上千万时不保留
    let sc = gets('class.media-body@tr.4@text', rr2);
    sc = (sc.match(/收藏\D*([\d\.wk千万]+)/) || ['', ''])[1].replace(/(\d*)k/, '$1千').replace(/(\.\d)\d*w/, '$1万').replace(/(\d{4,})\.\d万/, '$1万');
    //无收藏处理
    sc == '' ? '' : sc = '收藏:' + sc;
    //获取封面
    let cu = 'https://qidian.qpic.cn/qdbimg/349573/' + bkid + '/600';
    //获取粉丝，新书没有
    let fs = gets('class.media-body@tr.3@text', rr2);
    fs = (fs.match(/粉丝\D*([\d\.wk千万]+)/) || ['', ''])[1].replace(/(\d*)k/, '$1千').replace(/(\.\d)\d*w/, '$1万');
    if (fs) {
        fs = '粉丝:' + fs;
    }
    //获取盟主，可能没有，标签超额，混入简介
    let mz = gets('class.media-body@tr.4@text', rr2);
    mz = (mz.match(/盟主\D*(\d+)/) || ['', ''])[1];
    if (mz) {
        mz = '本书已有' + mz + '位盟主';
    }

    java.setContent(rr);
    //书籍信息
    //是否存在检查-101
    let lyc = gets('$.Result');
    //类型
    let lx = gets('$.*.BaseBookInfo.CategoryName');
    //二级分类
    let lx2 = gets('$.*.BaseBookInfo.SubCategoryName');
    //推荐
    let tj = gets('$.*.BaseBookInfo.RecommendAll');
    //标签，混上起点图
    //sc = sc>9999 ? 	(sc/10000).toFixed(2)+'万' : sc;
    tj = tj > 9999999 ? '推荐:' + (tj / 10000).toFixed() + '万' : tj > 9999 ? '推荐:' + (tj / 10000).toFixed(1) + '万' : tj > 0 ? '推荐:' + tj : '';
    let kd = [lx, tj, sc, fs];
    //字数
    let wc = gets('$.*.BaseBookInfo.WordsCnt');
    //投资
    let tz = gets('$.*.BaseBookInfo.NewBookInvestCount');
    tz = tz == -1 ? '' : '已有' + tz + '人投资本书';
    //状态
    let zt = gets('$.*.BaseBookInfo.BookStatus');
    //最新VIP章节
    let lcv = gets('$.*.BaseBookInfo.ChapterInfo.LastVipUpdateChapterName');
    //最新章节
    let lc = gets('$.*.BaseBookInfo.ChapterInfo.LastUpdateChapterName');
    //最新时间免费
    let lct = gets('$.*.BaseBookInfo.ChapterInfo.LastChapterUpdateTime');
    //最新时间vip
    let lct2 = gets('$.*.BaseBookInfo.ChapterInfo.LastVipChapterUpdateTime');
    //采用最新的
    if (lct2 > lct) {
        lct = lct2;
        lc = lcv;
    }
    lct = java.timeFormatUTC(lct, "yyyy年MM月dd日HH:mm", 288e5);

    //限免
    let xm = gets('$.*.BaseBookInfo.FreshManSimple.IsInBlackList');
  if (String(sinfo['限免链接'])&&xm==0&&lct2>0)
  kd.push("限免");
  java.put('xm', xm);

    //月票数量
    let yp = gets('$.*.BaseBookInfo.MonthTicketCount');
    yp = yp > 9999 ? (yp / 10000).toFixed(1) + '万' : yp;
    //新建时间
    let jt = gets('$.*.BaseBookInfo.JoinTime');
    jt = java.timeFormatUTC(jt, "yyyy/MM/dd", 288e5); //HH:mm
    //简介
    let jianjie = gets('$.*.BaseBookInfo.Description');
    //书名
    let bknm = gets('$.*.BaseBookInfo.BookName');

    //作者名，为空时用起点图
    au = gets('$.*.AuthorInfo.Author') || au || (book.author + []).replace('\u200b', '');
    //特定搜索功能
    if (source.getLoginInfoMap()["同名书籍共存"]=="✅") {
        au = '\u200b' + au;
    }
    book.author = au; //书架已存在时，改回去会报错
    //等级，出版书无
    let aul = gets('$.*.AuthorInfo.AuthorLevel');
    if (aul) {
        aul = ` (${aul})`;
    }
    //作品数，出版书无
    let aus = gets('$.*.AuthorInfo.BookCount');
    aus = aus == 0 ? gets('$..Publisher') : '已有' + aus + '本作品';
    //作者ID
    let auid = gets('$.*.AuthorInfo.AuthorId');
    //作者头像
    let auim = gets('$.*.AuthorInfo.RealImageUrl');
    //存头像
    java.put('auim', auim);
    //作者简介
    let aude = gets('$.*.AuthorInfo.AuthorDesc');
    //存作者说明
    java.put('aude', aude);

    //书单评论
    let sdjj = cache.getFromMemory('zsjjl' + bkid) || '';
    //编写加载简介
    let it = `<usehtml>
<p>${sdjj}${au}${aul} ${aus}</p>
${tz?`<p>${tz}</p>`:''}
${mz?`<p>${mz}</p>`:''}
<p>类型：${lx2}</p>
${tssd?`<p>${tssd}</p>`:''}
<p>月票：${yp}</p>
${tspf?`<p style="text-align: end">${tspf}  </p>`:''}
<p style="text-align: end"><i>${lct}</i>  </p>
<br>
<p>${jianjie.replace(/\n/g, "<br>")}</p>
<usehtml>`; //${jt}

    //不存在时反馈到简介
    if (lyc < 0) {
        it = '❗起点反馈：' + gets('$.Message') + '\n最新：' + book.latestChapterTitle + '\n本书id：' + bkid;
        //异常时标记该书,已下架
        java.put('yxj', 1);
    }

    //目录链接同书籍链接
    let tur = book.bookUrl.replace('pe":"lyc', 'pe":"l');
    //无脑更新书名
    book.name = bknm || book.name;
    //直接控制简介
    book.intro = it;
    lc = lc + ' • ' + lct;
    result = {
        nm: bknm,
        au: au,
        kd: kd,
        wc: wc,
        lc: lc,
        cu: cu,
        tur: tur
    };
}
