ruleContent.content:
@js:
let bkid = book.getVariable('bkid');

let [, zcid] = chapter.url.match(/^[^\,]+,([^\,]+)/);
zcid = java.base64Decode(zcid);
java.put("cid", zcid);
let uvip = book.getVariable("uvip" + zcid);
let bin = book.durChapterIndex;
let cin = chapter.index;
let sinfo = source.getLoginInfoMap();
let tsms = sinfo["调试模式"]=="✅";
let dpk = sinfo["段评"];
let dpkg = dpk=="✅"||dpk=="❗";

if (!dpkg&&chapter.imgUrl!='') {
    chapter.putImgUrl('');
}

if (chapter.isVolume()) {
	//卷章
	let url1 = QDSign("v1/chapterlist/getvolumeinfo", ["bookId=" + bkid, "volumeCode=" + zcid]);
	result = java.ajax(url1);
	result = gets('$..VolumeDescription', result);
}
else if (zcid.startsWith('彩')) {
	//彩蛋
	zcid = zcid.slice(1);
	let url3 = QDSign("v3/midpage/pageinfo", ["bookId=" + bkid, "chapterId=" + zcid, "needAdv=0"]);
	result = java.ajax(url3);
	let rr = '';
	let zssj = cache.get('zssj').split(',');
	let pg = com.jayway.jsonpath.JsonPath.parse(result).read('$..MidPageList[*]');
	for (let cpg of pg) {
		book.imageStyle = '';
		let sl = com.jayway.jsonpath.JsonPath.parse(cpg);
		let pid = (sl.read('$..PageId') + '').slice(1, -1);
		let slc = sl.read('$..Widgets[*].Data');
		for (let char of slc) {
			let bt = char.Text;
			let imu = char.ImgUrl;
			let viu = char.VideoCoverUrl;
			let vurl = char.VideoUrl;
			let [, sid] = (char + '').match(/\WSourceId\D+(\d+)/) || [];

			let type = 3;
			let ua = `Dalvik/2.1.0 (Linux; U; Android 10; ${zssj[1]} Build/UKQ1.230924.001)`;
			if (viu && vurl != '') {
				imu = viu;
				type = 1;
				rr += `
<img src="${imu},{"headers":{"User-Agent":"${ua}"},"click":"videoh('${vurl}','${bt}','${imu}','${bkid}','${zcid}')"}">点击图片，播放视频。`;
			} else {
				rr += `
<img src="${imu},{"headers":{"User-Agent":"${ua}"}}">`;
			}

			let url33 = QDSign("v1/midpage/danmu/get", ["bookId=" + bkid, "midpageId=" + pid, "resourceId=" + sid, "type=" + type, "timeAt=0", "seconds=10"]);
			result = java.ajax(url33);
			let dmt = '';
			let dms = jiesuo('', result, '$..Text');
			let hs = 1, ls = 1, zs = 0;
			let imt = '';
			let svg = () => `<svg width="1080" height="${hs * 70 + 10}" xmlns="http://www.w3.org/2000/svg">${imt}</svg>`;
			for (let dm of dms) {
				if (imt == '') imt = `<text fill="#${color()[0]}" opacity="0.9"  dominant-baseline="middle" font-weight="bold" font-size="48">`;
				dm = (dm + '').replace(/\[fn=(\d+)\]/g, (x, y) => { return emojisMap[y] });
				zs += (Math.random() * 30 | 0) / 10;
				zzs = zs + dm.length;
				if (zzs > 19) { hs++; zs = (Math.random() * 30 | 0) / 10; }
				imt += `<tspan x="${zs * 60}" y="${hs * 70}">${dm}</tspan>`;
				zs += dm.length;
				if (hs > 9) {
					imt += `</text>`;
					let img = `<img src="data:image/svg+xml;base64,${java.base64Encode(svg())},{"type":"img"}">`;
					rr += img;
					hs = 1; zs = 0; imt = '';
				}
			}
			if (imt != '') {
				imt += `</text>`;
				let img = `<img src="data:image/svg+xml;base64,${java.base64Encode(svg())},{"type":"img"}">`;
				rr += img;
			}
		}
	}
	result = rr;
} else if (chapter.isVip() || uvip == '2') {
	//VIP章
	let [, cid] = baseUrl.match(/^[^\,]+,([^\,]+)/);
	cid = java.base64Decode(cid);
	let bkbl = book.getVariable("custom") + '';
	//破解方式
	let pjfs = 
		/wxsck.com/.test(bkbl) ? 5 :
		/libahao.com|^篱笆/.test(bkbl) ? 4 :
		bkbl.includes(sdgurl)||bkbl.includes(dqurl) ? 3 :
		/^https?:/.test(bkbl) ? 2 :
		bkbl.startsWith('笔趣阁') ? 1 : 0;
		result = getresult(sinfo['限免链接']+'',book.getVariable('xm'),bkid,zcid,sinfo["限免key"]+'');
		if (result !=='' ) {java.put('xyy', ''); pjfs=-1;}
		if ((pjfs!=0||dpk=="❗")&&cid==zcid&&dpkg) {
			let dpurl = QDSign("v1/chapterreview/getchapterrepagesummary", ["bookId=" + bkid, "chapterId=" + zcid, "useImei=0"]);
			let dprr = jiesuo(dpurl,bkid,0,zcid);
			java.put("dp", dprr);
			//段评结束
			}
            else if (pjfs==0||!dpkg) chapter.putVariable("dp", null);
	if (pjfs > 0) {
		//笔趣阁替换
		//获取重定向地址头
		let cdx = java.get('cdx');
		//优先69的头，速读谷也需要
		if (pjfs != 1) cdx = bkbl.match(/http.{4}[^\/]+/)[0];
		//访问结果
		var pjt = '';
		let pjr = book.getVariable("zspj");

		function httu(url, fs) {
			let ck = '';
			if (fs == 3) ck = cookie.getCookie(cdx);
			if (fs == 4) ck = cookie.getCookie(lbhurl);
			let net = java.connect(gethd(url, ck));
			let bdy = net.body();
			ck = Array.from(
				net.headers()
					.values("Set-Cookie"))
				.map(x => String(x).replace(/;.*/, '')).join('; ');
			if (fs == 4) cookie.replaceCookie(lbhurl, ck);
			if (/^java\.net|^error/.test(bdy)) bdy = '';
			return bdy;
		}

		if (cid == zcid && pjr != '') {
			//第一页
			pjr = org.jsoup.Jsoup.parse(pjr);
			let ctitle = String(chapter.title);
			var [, cpx, cnm] = ctitle.split(/^([^章节回]+[章节回]|[^、：]+[、：]|\d{2,}.)/);
			cpx = cpx.replace(/^\s+|[\s、：\.]+$/g, '');
			cnm = cnm.replace(/^[、\s]+|\s+$/g, '');
			cnm || java.log('无标题名，序号为：' + cpx);

			//查找章节
			var pji = pjr.select('a:matchesWholeText(' + cpx + '.*' + cnm + ')').attr('href');
			if (pji == '' && /[（(].*[)）]/.test(cnm)) {
				//处理括号干扰
				let cnm2 = cnm.replace(/[（(].*[)）]/g, '.*');
				tsms && java.log('匹配0\n' + cpx + '♦' + cnm2);
				pji = pjr.select('a:matchesWholeText(' + cpx + '.*' + cnm2 + ')').attr('href');
			}

			let n1, n2;
			if (pji == '') {
				//用新定位限制
				let cdw = book.getVariable('cdw');
				cdw = JSON.parse(cdw);
				let index = cdw.findIndex(ob => ob.C == cid);
				var cdwqj = 0;
				for (let i = 0; i < index; i++) {
					/请假/.test(cdw[i].N) && cdwqj++;
				}
				n1 = index - 10;
				if (n1 < 0) n1 = 0;
				n2 = index + 10;
				tsms && java.log('匹配1\n' + cpx + '♦' + cnm + '\nn1：' + n1 + '，n2：' + n2);
				pji = pjr.select(`a:gt(${n1}):lt(${n2}):matchesWholeText([\\s章、：\\.]${cnm || '洛娅橙lyc'}\\s*\$)`).attr('href');
			}
			if (pji == '' && cnm) {
				//可能括号造成的
				let t = '[盟月票谢更求订读粉新]|合一';
				let zz = new RegExp(`[(（].+${t}.*[）)]|[(（].*${t}.+[）)]|【.+${t}.+】`, 'g');
				cnm = cnm
					.replace(zz, '') || '洛娅橙lyc';
				tsms && java.log('匹配2\n' + cpx + '♦' + cnm + '\nm1：' + n1 + '，n2：' + n2 + '\n' + zz);
				pji = pjr.select(`a:gt(${n1}):lt(${n2}):matchesWholeText(${cnm}\\s*\$)`).attr('href');
			}
			if (pji == '' && cnm) {
				//通匹括号和结尾符号
				//构建正则
				let zz = new RegExp('[(（].*[）)]$|【.*】$|（.{0,7}$');
				cnm = cnm
					.replace(zz, '')
					.replace(/[，。？！…～·、；\.…\-\s]+$/, '') || '洛娅橙橙lyc';
				n1 = (n1 - 40 < 0) ? 0 : (n1 - 10 - cdwqj);
				n2 = n2 + 10;
				tsms && java.log('匹配3\n' + cpx + '♦' + cnm + '\nn1：' + n1 + '，n2：' + n2 + '\n' + zz + '\n请假条' + cdwqj);
				pji = pjr.select(`a:gt(${n1}):lt(${n2}):matchesWholeText(${cnm})`).attr('href');
			}
			if (pji == '') {
				//错误率增高
				let cnm1 = (cnm || '标题为空依靠四位序号的情况').match(/[一-ꀀ]+/g);
				//构建正则
				let zz = /\d{4,}|[零一二三四五六七八九十百千万]{4,}/.test(cpx) ? (cpx + '|') : ''; //序号
				if (cnm.length > 3) {
					for (char of cnm1) zz = zz + char + '.*';
				}
				else zz = zz + '[\\s、：\.章]' + cnm + '$';
				n1 = n1 + 10;//反向提升防匹配旧章节
				n2 = n2 + 10;
				tsms && java.log('匹配4\n' + cpx + '♦' + cnm + '\nn1：' + n1 + '，n2：' + n2 + '\n' + zz);
				pji = pjr.select(`a:gt(${n1}):lt(${n2}):matchesWholeText(${zz})`).attr('href');
				tsms && java.log('解锁目录：\n' + pjr);
			}
			if (pji == '' && cnm) {
				n1 = (n1 > 999) ? (n1 - 10) : n1;
				//去除感叹词，干扰。极大放宽上限
				n2 = n2 + 80;
				cnm = cnm.replace(/吧$/, '');
				let zz = /[3456789]\d{2,}/.test(cpx) ? (cpx + '|') : '';
				zz = zz + cnm;
				tsms && java.log('匹配5\n' + cpx + '♦' + cnm + '\nn1：' + n1 + '，n2：' + n2 + '\n' + zz);
				pji = pjr.select(`a:gt(${n1}):lt(${n2}):matchesWholeText(${zz})`).attr('href');
			}

			if (pji == '') {
				//获取单章替换内容
				pjt = (book.getVariable("avip" + zcid) + '') || 'lyc';
				book.putVariable("nurl" + zcid, nextChapterUrl);
                java.put("nocontent",1);
				//失败
			} else {
				//成功
				pji = /^https?:/.test(pji) ? pji : pji.startsWith('//') ? ('https:' + pji) : (cdx + pji);
				tsms && java.log(pji);
				Packages.java.lang.Thread.sleep(Math.random() * 199 | 0);
				pjt = httu(pji, pjfs);
				cid = pji;
				if (pjt) {
					//处理繁体
					if (/69shux\.co/.test(pji)) pjt = java.t2s(pjt);
					//标记vip
					book.putVariable("uvip" + zcid, 2);
				}
				else java.log('初次访问正文失败');
			}

			//第一页结束
		} else if (pjr == '') {
			//无解锁目录
			pjt = '';
		} else {
			//下一页链接访问内容
			let tim = Math.floor(Math.random() * 1399);
			Packages.java.lang.Thread.sleep(tim);
			pjt = httu(cid, pjfs);
			if (!pjt) java.log('正文下一页访问失败');
		}

		let xyy = '';
		if (pjt == '') { result = ''; }
		else if (pjt == 'lyc') {
			result = '';
			if (bin == cin) java.toast('\n《' + book.name + '》\n' + chapter.title + '\n暂未解锁');
		}
		else {
			java.setContent(pjt);
			if (pjfs == 1) {
				xyy = gets('text.下一@href');
				if (xyy.includes('_')) xyy = cdx + xyy;
				else xyy = '';
				result = gets('#chaptercontent@html');
			} else if (pjfs == 2) {
				//69的正文匹配
				result = java.getElement('.content||.txtnav||.contxt||#txtcontent||#txtright');
				if (result == '' && bin == cin) java.toast('\n69正文链接访问异常');
				result.select('script, h1, .txtinfo, .chase-book-btn').remove();
			} else if (pjfs == 3) {
				xyy = gets('text.下一页@href');
				if (xyy.includes('-')) xyy = cdx + xyy;
				else xyy = '';
				//速读谷正文
				result = java.getElement('.con');
				if (result == '' && bin == cin) java.toast('\n速读谷/得奇正文链接访问异常');
			} else if (pjfs == 4) {
				//篱笆好
				xyy = gets('a:matchesWholeOwnText(^下一页)@href');
				let xyy2 = xyy.match(/\d+\/\d+/) || '';
				if (cid.includes(xyy2)) {
					if (/_\d+\.html/.test(xyy)) xyy = cdx + xyy;
					else xyy = '';
					result = java.getElement('#chapterContent');
					result.select('a').remove();
					if (result == '' && bin == cin) java.toast('\n篱笆好正文链接访问异常');
				} else { java.toast('\n篱笆好资源暂未更新'); result = xyy = ''; }
			}
			else if (pjfs == 5) {
				//万相书城
				//xyy = gets('a:contains(下一页)@href');
                xyy = gets('.text-center@a.-1@href');
				if (xyy.includes('_')) xyy = cdx + xyy;
				else xyy = '';
				result = gets('#cont-body@html');

				} else { java.toast('❌'); }

			//格式html，方便净化
			result = java.htmlFormat(gets('@html', result));
			result = String(result);
		}
		//下一页
		java.put('xyy', xyy);

		if (pjfs == 1) {
			//笔趣阁净化
			result = result.replace(/\s*（.*阅读模式.*）\s*|\s*请收藏.*\.(?:com|cc|icu|cfd)/g, '').replace(/([一-ꀀ])$/, '$1🎭');
		} else if (pjfs == 2) {
			//69书吧净化
			let z1 = '[一⊥]+';
			let zz = new RegExp(`^[^，。？“”]{0,19}[6六]${z1}[9九]${z1}书${z1}吧[^，。？“”]{0,9}\$`, 'gm');
			result = result.replace(zz, '');
			//69繁体站
			if (/69shux\.co/.test(pji)) {
				let z2 = `[^\\sa-z，。？！：；…～“”、（）—‘’·《》￥〈〉【】〖〗『』「」．,?!:;…~'"一-ꀀ]|[乂爪]`;
				let z3 = "\\.*";
				let zz = new RegExp(`请${z3}您${z3}收${z3}藏${z3}6${z3}9${z3}书${z3}吧${z3}！|(?:${z2})(?:${z2}|[^\\S\\n]){6,}|^[^，。？“”]{0,9}首${z1}发${z1}内${z1}容[^，。？“”]{0,19}\$`, 'gmi');
				result = result.replace(zz, '');
			}
		} else if (pjfs == 4) {
