function hasValidSecretKey() {
    var key = getSecretKey();    
    return key && key.trim() != "";
}

function login() {
    if (hasValidSecretKey()) {
        return;
    }

    var email = getemail();
    if (!email || email.trim() === "") {
        java.toast("邮箱不能为空");
        return;
    }

    var host = getHost();
    var url = host + "genkey/,";

    var body = JSON.stringify({"email": email});
    var post = JSON.stringify({
        "body": body,
        "method": "POST"
    });

    url += post;
    var response = java.ajax(url);

    try {
        var data = JSON.parse(response);
        if (data.c === 200) {
            java.toast(data.m);
        } else {
            java.toast("请求失败: " + data.m);
        }
    } catch (e) {
        java.toast("解析响应失败: " + e);
    }
}

function ConfigManager() {
    var self = this;
    var DEFAULT_SOURCE = "聚合";
    var DEFAULT_TAG = "小说";
    var AGGREGATE_SOURCE = "聚合";

    this.data = {
        source: DEFAULT_SOURCE,
        tag: DEFAULT_TAG,
        forceListen: false,
        voice: "default"
    };

    this.sources = [];
    this.sourceTags = {};
    this.defaultSource = DEFAULT_SOURCE;
    this.allTags = new Set();

    this.init = function() {
        var stored = source.getVariable();
        try {
            if (stored) {
                var parsed = JSON.parse(stored);

                if (!parsed.forceListen) parsed.forceListen = false;
                if (!parsed.voice) parsed.voice = "default";

                self.data = parsed;
                java.toast("配置加载成功");
                return;
            }
        } catch(e) {
            java.log("解析存储数据失败: " + e);
        }

        self.data = {
            source: DEFAULT_SOURCE,
            tag: DEFAULT_TAG,
            mode: "default",
            forceListen: false,
            voice: "default"
        };
        self.save();
        java.toast("\n首次使用\n已初始化为默认配置\n源: " + DEFAULT_SOURCE + "\n模式: " + DEFAULT_TAG);
    };

    this.save = function() {
        source.setVariable(JSON.stringify(self.data));
    };

    this.fetchSources = function() {
        if (!hasValidSecretKey()) {
            java.toast("请先填写有效的密钥信息");
            return false;
        }

        var url = getHost() + "sources?key=" + getSecretKey();
        var response = java.ajax(url);
        try {
            var data = JSON.parse(response);
            if (data.c === 200) {
                self.sources = data.data.sources;
                self.defaultSource = data.data.default_source || DEFAULT_SOURCE;
                self.sourceTags = {};
                self.allTags = new Set();

                for (var i = 0; i < self.sources.length; i++) {
                    var src = self.sources[i];
                    var tags = [DEFAULT_TAG];

                    if (src.supported_types && src.supported_types.length > 0) {
                        tags = src.supported_types;
                    }

                    tags.forEach(function(tag) {
                        self.allTags.add(tag);
                    });

                    self.sourceTags[src.id] = tags;
                }

                self.sourceTags[AGGREGATE_SOURCE] = Array.from(self.allTags);

                java.putSharedData("source_tags", JSON.stringify(self.sourceTags));
                java.putSharedData("default_source", self.defaultSource);

                return true;
            }
        } catch(e) {
            java.log("获取源信息失败: " + e);
        }
        return false;
    };

    this.setSource = function(sourceId) {
        self.data.forceListen = false;

        if (sourceId === AGGREGATE_SOURCE) {
            self.data.source = AGGREGATE_SOURCE;
            self.save();
            java.toast("\n已切换到聚合源\n支持所有标签!\n强制听书已关闭");
            self.showCurrent();
            return true;
        }

        if (!self.sourceTags.hasOwnProperty(sourceId)) {
            java.toast("\n错误: 不支持的源 - " + sourceId);
            return false;
        }

        self.data.source = sourceId;

        var currentTags = self.sourceTags[sourceId] || [DEFAULT_TAG];
        if (currentTags.indexOf(self.data.tag) === -1) {
            self.data.tag = currentTags[0] || DEFAULT_TAG;
            java.toast("\n源切换成功!\n模式已自动调整为: " + self.data.tag + "\n强制听书已关闭");
        } else {
            java.toast("\n源切换成功!\n强制听书已关闭");
        }

        self.save();
        self.showCurrent();
        return true;
    };

    this.setTag = function(tag) {
        self.data.forceListen = false;

        if (self.data.source === AGGREGATE_SOURCE) {
            self.data.tag = tag;
            self.save();
            java.toast("\n模式设置成功: " + tag + "\n强制听书已关闭");
            self.showCurrent();
            return true;
        }

        var currentTags = self.sourceTags[self.data.source] || [DEFAULT_TAG];
        if (currentTags.indexOf(tag) === -1) {
            java.toast("\n错误: 当前源不支持模式 - " + tag);
            return false;
        }

        self.data.tag = tag;
        self.save();
        java.toast("\n模式设置成功: " + tag + "\n强制听书已关闭");
        self.showCurrent();
        return true;
    };

    this.toggleForceListen = function() {
        if (self.data.tag != "小说") {
            java.toast("\n错误: 强制听书只支持小说模式\n当前模式: " + self.data.tag);
            return false;
        }

        self.data.forceListen = !self.data.forceListen;
        self.save();

        var status = self.data.forceListen ? "开启" : "关闭";
        java.toast("\n强制听书 " + status);
        return true;
    };

    this.setVoice = function(voiceId) {
        self.data.voice = voiceId;
        self.save();
        java.toast("\n音色设置成功: " + voiceId);
        return true;
    };

    this.showCurrent = function() {
        var msg = "\n当前配置:";
        msg += "\n源: " + self.data.source;
        msg += "\n模式: " + self.data.tag;
        msg += "\n强制听书: " + (self.data.forceListen ? "开启" : "关闭");
        msg += "\n音色: " + self.data.voice;

        if (self.data.source === AGGREGATE_SOURCE) {
            msg += "\n\n聚合源支持所有模式:";
            var allTagsArray = Array.from(self.allTags);
            if (allTagsArray.length > 0) {
                for (var i = 0; i < Math.min(5, allTagsArray.length); i++) {
                    msg += "\n- " + allTagsArray[i];
                }
                if (allTagsArray.length > 5) {
                    msg += "\n...等 " + allTagsArray.length + " 个模式";
                }
            }
        } else {
            var tags = self.sourceTags[self.data.source];
            if (tags && tags.length > 0) {
                msg += "\n\n支持的模式: " + tags.join(", ");
            }
        }

        if (self.data.forceListen) {
            msg += "\n\n强制听书已开启:";
            msg += "\n- 将使用听书功能";
            msg += "\n- 使用音色: " + self.data.voice;
        }

        java.longToast(msg);
    };

    this.showAllSources = function() {
        if (self.sources.length === 0) {
            java.toast("\n没有可用的源信息，请先填写有效密钥");
            return;
        }

        var msg = "可用源列表:";
        for (var i = 0; i < self.sources.length; i++) {
            var src = self.sources[i];
            msg += "\n\nID: " + src.id;
            msg += "\n名称: " + src.name;

            if (src.supported_types && src.supported_types.length > 0) {
                msg += "\n支持模式: " + src.supported_types.join(", ");
            }
        }

        msg += "\n\nID: " + AGGREGATE_SOURCE;
        msg += "\n名称: 聚合源";
        msg += "\n支持模式: 所有模式";

        java.longToast(msg);
    };

    this.reset = function() {
        self.data = {
            source: self.defaultSource || DEFAULT_SOURCE,
            tag: DEFAULT_TAG,
            mode: "default",
            forceListen: false,
            voice: "default"
        };
        self.save();
        java.toast("\n已重置为默认配置");
        self.showCurrent();
    };

    this.showSecretKey = function() {
        var key = getSecretKey();
        if (hasValidSecretKey()) {
            java.toast("当前密钥: " + key);
        } else {
            java.toast("未设置有效密钥");
        }
    };

    this.init();
}

var config = new ConfigManager();

if (hasValidSecretKey()) {
    config.fetchSources();
} else {
    java.toast("检测到未设置密钥");
}

